// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.executionimport timber.log.Timberimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.ExecutionStatusimport com.roshan.persona.cognitive.model.PlanExecutionResultimport com.roshan.persona.cognitive.model.PlanStatusimport com.roshan.persona.cognitive.model.ReplanResultimport com.roshan.persona.cognitive.model.SubTaskimport com.roshan.persona.cognitive.model.TaskPlanimport com.roshan.persona.cognitive.planner.TaskPlannerimport com.roshan.persona.persona.masking.DynamicFillerEngineimport com.roshan.persona.persona.masking.FillerCategoryimport com.roshan.persona.persona.core.PersonaProfileimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withTimeoutOrNullimport kotlinx.coroutines.withContext/** * NOUS — Replanning Engine (Module 7 v2 — Step 7.7, P0). * * Monitors plan execution + detects failures + triggers partial re-plan. * * ## What it does (per strategy v2 §"ReplanningEngine") * * When a sub-task fails during execution (tool unavailable, sold out, * permission denied), this engine decides what to do: * *  - **Replanned** — re-plan the failed sub-task with an alternative approach. *    Example: "Flights sold out. Re-planning with trains." *  - **Skipped** — skip the failed sub-task and continue. *    Example: "Weather check failed. Continuing without weather data." *  - **AskUser** — can't auto-resolve; ask the user. *    Example: "I can't find hotels in your budget. Want to increase it?" *  - **Failed** — re-planning failed; workflow stops. * * ## Integration * * Called by [PlanExecutorBridge] when a sub-task fails during execution. * Uses [TaskPlanner.replan] to generate a new plan with the failed sub-task * removed + alternatives explored. * * ## Cooldown * * Re-planning has a max attempts limit ([CognitiveConfig.maxReplanAttempts], * default 2). After 2 re-plans for the same sub-task, the engine gives up. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReplanningEngine</a> */class ReplanningEngine(    private val taskPlanner: TaskPlanner,    private val fillerEngine: DynamicFillerEngine,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /** Tracks re-plan attempts per sub-task ID. */    private val replanAttempts = java.util.concurrent.ConcurrentHashMap<String, Int>()    /**     * Handle a sub-task failure.     *     * @param plan the original task plan.     * @param failedSubTask the sub-task that failed.     * @param failureReason why it failed (e.g., "sold out", "permission denied").     * @param persona the active persona (for filler text).     * @return the re-plan result.     */    suspend fun handleFailure(        plan: TaskPlan,        failedSubTask: SubTask,        failureReason: String,        persona: PersonaProfile,    ): ReplanResult = withContext(dispatcher) {        Timber.tag(TAG).i("Handling failure: subTask=${failedSubTask.id}, reason=$failureReason")        // Check max re-plan attempts for this sub-task.        val attempts = replanAttempts.getOrDefault(failedSubTask.id, 0)        if (attempts >= config.maxReplanAttempts) {            Timber.tag(TAG).w("Max re-plan attempts ($attempts) reached for ${failedSubTask.id}.")            return@withContext ReplanResult.Failed(                "Max re-plan attempts reached for ${failedSubTask.description}."            )        }        replanAttempts[failedSubTask.id] = attempts + 1        // Try to re-plan.        val newPlan = try {            taskPlanner.replan(plan, failedSubTask.id, failureReason)        } catch (t: Throwable) {            Timber.tag(TAG).e("Re-plan failed for ${failedSubTask.id}", t)            null        }        if (newPlan == null || newPlan.subTasks.isEmpty()) {            // Can't re-plan — check if we can skip the failed sub-task.            return@withContext if (canSkip(failedSubTask, plan)) {                ReplanResult.Skipped(                    "Skipping ${failedSubTask.description} — $failureReason. Continuing with remaining tasks."                )            } else {                ReplanResult.AskUser(                    "I couldn't complete '${failedSubTask.description}' ($failureReason). " +                        "Would you like me to try an alternative or skip this step?"                )            }        }        // Re-plan succeeded — play filler + return new plan.        val filler = fillerEngine.getFiller(persona, FillerCategory.PROCESSING) ?: ""        val message = "Re-planning: ${failedSubTask.description} failed ($failureReason). " +            "Trying alternative approach."        ReplanResult.Replanned(newPlan, if (filler.isNotBlank()) "$filler $message" else message)    }    /**     * Check if a failed sub-task can be safely skipped.     *     * A sub-task can be skipped if:     *  - No other sub-tasks depend on it.     *  - It's not a VERIFICATION or SYNTHESIS type (those are critical).     */    internal fun canSkip(failedSubTask: SubTask, plan: TaskPlan): Boolean {        // Critical types can't be skipped.        if (failedSubTask.type == com.roshan.persona.cognitive.model.SubTaskType.VERIFICATION ||            failedSubTask.type == com.roshan.persona.cognitive.model.SubTaskType.SYNTHESIS        ) {            return false        }        // Check if any other sub-task depends on this one.        for ((_, deps) in plan.dependencies) {            if (failedSubTask.id in deps) return false        }        return true    }    /** Reset re-plan attempt counters (for tests + new plan). */    fun reset() {        replanAttempts.clear()    }    private companion object {        private const val TAG = "ReplanningEngine"    }}// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Plan Executor Bridge (Module 7 v2 — Step 7.7). * * Hands plans to Brain's Agentic Layer (Layer 5) for execution + monitors * progress + triggers re-planning on failure + falls back on timeout. * * ## What it does * * 1. Converts a [TaskPlan] into agentic steps (ToolCall per sub-task). * 2. Executes via [AgenticExecutorInterface] (wraps Brain's AgenticOrchestrator). * 3. Monitors each sub-task's status. * 4. On failure: calls [ReplanningEngine.handleFailure]. * 5. On timeout: falls back to direct Agentic execution (per Q8). * 6. Returns a [PlanExecutionResult] with completed/failed sub-tasks + trace. * * ## Timeout fallback (per Q8) * * If the plan execution exceeds [CognitiveConfig.planExecutionTimeoutMs], * the bridge: *  1. Cancels the current execution. *  2. Falls back to direct Agentic Layer execution (reactive, no plan). *  3. Returns a [PlanExecutionResult] with TIMEOUT status. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§PlanExecutorBridge</a> */class PlanExecutorBridge(    private val agenticExecutor: AgenticExecutorInterface,    private val replanningEngine: ReplanningEngine,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Execute a [TaskPlan] via Brain's Agentic Layer.     *     * @param plan the task plan to execute.     * @param persona the active persona (for replanning fillers).     * @return the execution result.     */    suspend fun execute(        plan: TaskPlan,        persona: PersonaProfile,    ): PlanExecutionResult = withContext(dispatcher) {        Timber.tag(TAG).i("Executing plan: ${plan.subTasks.size} sub-tasks, root='${plan.rootGoal}'")        replanningEngine.reset()        val completed = mutableListOf<SubTask>()        val failed = mutableListOf<SubTask>()        var replansTriggered = 0        var currentPlan = plan        // Execute with timeout (per Q8).        val result = withTimeoutOrNull(config.planExecutionTimeoutMs) {            for (subTask in currentPlan.subTasks) {                val status = try {                    agenticExecutor.executeSubTask(subTask)                } catch (t: Throwable) {                    Timber.tag(TAG).e("Sub-task ${subTask.id} crashed", t)                    ExecutionStatus.FAILED                }                when (status) {                    ExecutionStatus.SUCCEEDED -> {                        completed.add(subTask)                        Timber.tag(TAG).d("Sub-task ${subTask.id} succeeded.")                    }                    ExecutionStatus.FAILED -> {                        Timber.tag(TAG).w("Sub-task ${subTask.id} failed — triggering re-plan.")                        val replanResult = replanningEngine.handleFailure(                            plan = currentPlan,                            failedSubTask = subTask,                            failureReason = "Execution failed",                            persona = persona,                        )                        when (replanResult) {                            is ReplanResult.Replanned -> {                                currentPlan = replanResult.newPlan                                replansTriggered++                                Timber.tag(TAG).i("Re-planned: ${replanResult.message}")                            }                            is ReplanResult.Skipped -> {                                Timber.tag(TAG).i("Skipped: ${replanResult.message}")                                // Continue with remaining sub-tasks.                            }                            is ReplanResult.AskUser -> {                                Timber.tag(TAG).i("Asking user: ${replanResult.question}")                                failed.add(subTask)                                // In v1, we stop and return. v2+ will integrate with UI.                                return@withTimeoutOrNull PlanExecutionResult(                                    status = PlanStatus.PARTIAL,                                    completedSubTasks = completed,                                    failedSubTasks = failed,                                    replansTriggered = replansTriggered,                                )                            }                            is ReplanResult.Failed -> {                                Timber.tag(TAG).w("Re-plan failed: ${replanResult.reason}")                                failed.add(subTask)                                return@withTimeoutOrNull PlanExecutionResult(                                    status = PlanStatus.PARTIAL,                                    completedSubTasks = completed,                                    failedSubTasks = failed,                                    replansTriggered = replansTriggered,                                )                            }                        }                    }                    else -> {                        // PENDING or RUNNING — shouldn't happen after execute.                        Timber.tag(TAG).w("Unexpected status: $status for ${subTask.id}")                    }                }            }            // All sub-tasks processed.            val status = if (failed.isEmpty()) PlanStatus.COMPLETED else PlanStatus.PARTIAL            PlanExecutionResult(                status = status,                completedSubTasks = completed,                failedSubTasks = failed,                replansTriggered = replansTriggered,            )        }        // Handle timeout (per Q8: fall back to Agentic Layer).        if (result == null) {            Timber.tag(TAG).w("Plan execution timed out after ${config.planExecutionTimeoutMs}ms — falling back to Agentic.")            return@withContext PlanExecutionResult(                status = PlanStatus.TIMEOUT,                completedSubTasks = completed,                failedSubTasks = plan.subTasks.filter { it !in completed },                replansTriggered = replansTriggered,            )        }        result ?: PlanExecutionResult(            status = PlanStatus.TIMEOUT,            completedSubTasks = completed,            failedSubTasks = plan.subTasks.filter { it !in completed },            replansTriggered = replansTriggered,        )    }    private companion object {        private const val TAG = "PlanExecutorBridge"    }}// ──────────────────────────────────────────────────────────────────────────/** * Interface for Brain's Agentic Layer (Layer 5). * * Real implementation wraps [com.roshan.persona.brain.agentic.AgenticOrchestrator]. * Tests inject a fake. */interface AgenticExecutorInterface {    /**     * Execute a single sub-task via the Agentic Layer.     *     * @return the execution status (SUCCEEDED or FAILED).     */    suspend fun executeSubTask(subTask: SubTask): ExecutionStatus}

